   qm_register($db,$state,(string)($_SESSION['owner_invite_hash']??''),(string)($_POST['username']??''),(string)($_POST['password']??''),(string)($_POST['confirm']??''),isset($_POST['consent']));cap_store($db,$rev,$state);$db->commit();unset($_SESSION['owner_invite_hash']);$message='Registration complete. Keep your username and password. The managing agent will send a meeting invitation when voting is open.';
