 $db->beginTransaction();$rawState=$db->query('SELECT payload FROM quorum_workspace WHERE id=1')->fetchColumn();if($rawState===false)throw new CaptureError('Meeting workspace unavailable.',503);$state=cap_clean_state(json_decode($rawState,true,512,JSON_THROW_ON_ERROR));$owner=qm_owner_session($db,$state);
