<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quorum · Owner voting</title><style>body{font:16px system-ui;background:#f4f7f5;color:#174333;margin:0}main{max-width:760px;margin:35px auto;padding:20px}section{padding:24px;background:white;border:1px solid #d7e0d9;border-radius:12px;margin:18px 0}h1{font-size:28px}label{display:block;margin:14px 0 6px}input:not([type=checkbox]):not([type=radio]){font:inherit;box-sizing:border-box;padding:12px;width:100%;border:1px solid #9cad9f;border-radius:6px}button{font:inherit;padding:12px 22px;background:#174c3e;color:white;border:0;border-radius:6px;cursor:pointer}.error{padding:16px;background:#ffe1da}.notice{padding:16px;background:#fff1ce}.choice{display:inline-block;margin:10px 15px 10px 0}a{color:#174c3e}small{display:block;color:#59665d}</style></head><body><main><strong>quorum.</strong><h1><?=h($state['hoa']??'Owner voting')?></h1>
<?php if($error): ?><p class="error" role="alert"><?=h($error)?></p><?php endif ?><?php if($message): ?><p class="notice" role="status"><?=h($message)?></p><?php endif ?>
<?php if($owner): ?><p><?=h($owner['name'].' · Property '.$owner['unit'])?></p><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button>Sign out</button></form>
<?php if($case): ?><p class="notice"><?=$case['status']==='disputed'?'Representation disputed: submissions are retained but excluded from results and quorum until administrator review.':'The administrator has recorded a representation decision. Contact the managing agent if it needs review.'?></p><?php endif ?>
