<?php elseif(($state['status']??'')==='live'): ?><section><h2><?=h($state['meeting'])?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="vote"><?php foreach($state['motions'] as $m): ?><fieldset><legend><?=h($m['title'])?></legend><p><?=h($m['description']??'')?></p><?php foreach(['For','Against','Abstained'] as $choice): ?><label class="choice"><input type="radio" name="motion-<?=h($m['id'])?>" value="<?=h($choice)?>" required> <?=h($choice)?></label><?php endforeach ?></fieldset><?php endforeach ?><label><input type="checkbox" name="confirmed" required> I reviewed all choices and confirm this complete ballot is my submission.</label><p>Submission is final. If a proxy also claims to represent you, both submissions will be held for administrator adjudication.</p><button>Submit my ballot</button></form></section>
